L11_1 = "\234\179\160\237\150\137 \235\129\157\236\151\144 \234\184\176\235\139\164\235\166\172\235\138\148 \234\178\131\236\157\180 \235\136\136\235\182\128\236\139\160 \235\179\180\236\131\129\236\157\180\235\158\128 \235\178\149\236\157\128 \236\151\134\235\139\164. \236\158\172\235\172\188\235\143\132 \234\178\189\236\154\176\236\151\144 \235\148\176\235\157\188\236\132\160 \235\143\133\236\157\180 \235\144\152\234\177\176\235\138\152."
