L11_1 = "\232\139\166\232\161\140\227\129\174\230\156\171\227\129\171\229\190\133\227\129\164\227\130\130\227\129\174\227\129\140\232\188\157\227\129\139\227\129\151\227\129\132\229\160\177\233\133\172\227\129\168\227\129\175\233\153\144\227\130\137\227\129\170\227\129\132\227\128\130\232\178\161\227\130\130\230\153\130\227\129\168\227\129\151\227\129\166\230\175\146\227\129\168\227\129\170\227\130\139\227\130\130\227\129\174\227\128\130"
